    fillDictionary("hint_2_2_icon", "target_nobody", "target_nobody", "target_nobody");
    fillDictionary("hint_3_1_icon", "goblin", "goblin", "goblin");
    fillDictionary("hint_3_2_icon", "goblin", "goblin", "goblin");
